CREATE OR REPLACE FUNCTION ECAMS.SYSHOMEPATH
(SYSCD varchar2,
RSRCCD varchar2)
return VARCHAR2
IS
    V_DIRPATH   VARCHAR2(200);
    VCNT        INTEGER;

BEGIN
    V_DIRPATH := NULL;
    SELECT A.CM_VOLPATH
      INTO V_DIRPATH
      FROM CMM0031 A,CMM0030 B,CMM0038 C
     WHERE B.CM_SYSCD=SYSCD
       AND B.CM_SYSCD=A.CM_SYSCD
       AND B.CM_DIRBASE=A.CM_SVRCD
       AND A.CM_CLOSEDT IS NULL
       AND NVL(A.CM_CMPSVR,'N')='Y'
       AND A.CM_SYSCD=C.CM_SYSCD
       AND A.CM_SVRCD=C.CM_SVRCD
       AND A.CM_SEQNO=C.CM_SEQNO
       AND C.CM_RSRCCD=RSRCCD
       AND ROWNUM=1;

    IF V_DIRPATH IS NULL THEN
       SELECT A.CM_VOLPATH
         INTO V_DIRPATH
         FROM CMM0031 A,CMM0030 B,CMM0038 C
        WHERE B.CM_SYSCD=SYSCD
          AND B.CM_SYSCD=A.CM_SYSCD
          AND B.CM_DIRBASE=A.CM_SVRCD
          AND A.CM_CLOSEDT IS NULL
          AND A.CM_SYSCD=C.CM_SYSCD
          AND A.CM_SVRCD=C.CM_SVRCD
          AND A.CM_SEQNO=C.CM_SEQNO
          AND C.CM_RSRCCD=RSRCCD
          AND ROWNUM=1;
    END IF;
    return V_DIRPATH;
END ;